Not Deneyap Kart ile IMU uygulaması yapacak sınıflar ‘arduino ide ’ye aşağıdaki kod parçacığını girmelidir:

#include "deneyap.h" #include "lsm6dsm.h"

#define delayms 700

LSM6DSM IMU; // IMU icin Class tanimlamasi

void setup() { Serial.begin(115200); // Seri haberlesme baslatildi IMU.begin(); // IMU ayarlari konfigure edildi }

void loop() { Serial.println("\nAkselerometre degerleri\n"); Serial.print("X ekseni\t: "); Serial.println(IMU.readFloatAccelX()); // X-eksen akselerometre verisi okuma delay(delayms); Serial.print("Y ekseni\t: "); Serial.println(IMU.readFloatAccelY()); // Y-eksen akselerometre verisi okuma delay(delayms); Serial.print("Z ekseni\t: "); Serial.println(IMU.readFloatAccelZ()); // Z-eksen akselerometre verisi okuma delay(delayms);

Serial.println("\nGyro degerleri\n"); Serial.print("X ekseni\t: "); Serial.println(IMU.readFloatGyroX()); // X-eksen gyro verisi okuma delay(delayms); Serial.print("Y ekseni\t: "); Serial.println(IMU.readFloatGyroY()); // Y-eksen gyro verisi okuma delay(delayms); Serial.print("Z ekseni\t: "); Serial.println(IMU.readFloatGyroZ()); // Z-eksen gyro verisi okuma delay(delayms);

}

