bool ros_servis_bidirimi(ilk_paket::servis_ornegi::Request &req, ilk_paket::servis_ornegi::Response &res) { switch (req.islem) { case '+': res.sonuc= req.a + req.b; ROS_INFO("%.2f %c %.2f = %.2f",req.a,req.islem,req.b,res.sonuc); break; case '-': res.sonuc= req.a - req.b; ROS_INFO("%.2f %c %.2f = %.2f",req.a,req.islem,req.b,res.sonuc); break; case '*': res.sonuc= req.a * req.b; ROS_INFO("%.2f %c %.2f = %.2f",req.a,req.islem,req.b,res.sonuc); break; case '/': res.sonuc= req.a / req.b; ROS_INFO("%.2f %c %.2f = %.2f",req.a,req.islem,req.b,res.sonuc); break; default: break; } return true; }

